<div class="page-heading"><div><div class="eyebrow">YOUR WHOLESALE SHELVES</div><h1>Product listings<span class="green">.</span></h1><p>Keep inventory, pricing and pack details up to date.</p></div><a class="btn btn-primary" href="/listing/edit">+ Add listing</a></div><div class="table-panel"><table><thead><tr><th>Product</th><th>Pack</th><th>Price</th><th>Stock</th><th>Status</th><th>Manage</th></tr></thead><tbody><?php foreach($offers as $o):?><tr><td><strong><?= e($o['name']) ?></strong><small><?= e($o['sku']) ?></small></td><td><?= e($o['pack_size'].' '.$o['unit']) ?></td><td><?= money($o['price']) ?><small>Min <?= $o['min_qty'] ?></small></td><td><?= $o['stock'] ?> packs</td><td><span class="badge soft-badge"><?= $o['archived']?'Archived':'Active' ?></span></td><td><div class="inline-form"><a href="/listing/edit?id=<?= $o['id'] ?>" class="btn btn-outline-secondary btn-sm">Edit</a><form action="/listing/archive" method="post"><?= csrf() ?><input type="hidden" name="id" value="<?= $o['id'] ?>"><button class="btn btn-outline-secondary btn-sm"><?= $o['archived']?'Restore':'Archive' ?></button></form></div></td></tr><?php endforeach;?></tbody></table><?php if(!$offers):?><div class="empty-state"><h2>Your first listing starts here.</h2><a href="/listing/edit" class="btn btn-primary">Create listing</a></div><?php endif;?></div>
